const input = $json.output;

// Remove the markdown code block formatting (```json ... ```)
const cleaned = input
  .replace(/```json\n?/, '')
  .replace(/```/, '')
  .trim();

// Parse the cleaned string into a JSON object
const parsed = JSON.parse(cleaned);

// Return the parsed JSON so the next node can use it
return [{ json: parsed }];

// Fetch raw output (works whether inside array or object)
const raw = items?.[0]?.json?.output || items?.[0]?.json?.response || JSON.stringify(items[0].json);

// --- Utility: recursively unescape multiple layers ---
function unescapeDeep(str) {
  let prev;
  let text = str;
  let attempts = 0;

  while (attempts < 8 && text !== prev) {
    prev = text;
    text = text
      .replace(/^```json|```$/g, '')       // remove code fences
      .replace(/\\r\\n|\\n/g, '\n')        // newline escape
      .replace(/\\t/g, '\t')               // tab escape
      .replace(/\\"/g, '"')                // quote escape
      .replace(/\\\\/g, '\\');             // double backslashes
    attempts++;
  }
  return text.trim();
}

// --- Utility: find the largest JSON-like object in a text ---
function extractJSONBlock(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) {
    throw new Error("No JSON braces found in output");
  }
  return text.slice(start, end + 1);
}

// --- Recursive parser that keeps trying deeper levels ---
function deepParse(input) {
  if (typeof input !== 'string') return input;

  let text = unescapeDeep(input);
  for (let i = 0; i < 8; i++) {
    try {
      return JSON.parse(text);
    } catch (err) {
      // Extract inner JSON if extra characters remain
      try {
        const inner = extractJSONBlock(text);
        text = unescapeDeep(inner);
      } catch {
        // No more braces to extract
      }
    }
  }
  throw new Error("Failed to parse final JSON after multiple cleanup passes");
}

// --- Step 1: Convert any wrapped object like [{output:"..."}] ---
let candidate = raw;
if (Array.isArray(candidate) && candidate[0]?.output) {
  candidate = candidate[0].output;
} else if (typeof candidate === 'object') {
  candidate = JSON.stringify(candidate);
}

// --- Step 2: Clean deeply ---
const parsed = deepParse(candidate);

// --- Step 3: Output cleaned JSON for next node ---
return [{ json: { cleaned_folder_json: parsed } }];

// Get the first item (adjust if multiple items)
const item = items[0].json;

// Parse the endpoints JSON string into real JSON
let endpoints;
try {
  if(item["endpoints json"] != ""){
    endpoints = JSON.parse(item["endpoints json"]);
  }

} catch (err) {
    throw new Error("Failed to parse endpoints JSON: " + err.message);
}

// Return the project info along with parsed endpoints
return [{
    json: {
        project_name: item["project name"],
        project_description: item["project decription"],
        endpoints: endpoints,
        submittedAt: item.submittedAt,
        formMode: item.formMode
    }
}];

