import json
import zipfile
import io
import base64

# === INPUT ===
# Get JSON from previous node
project = _input.first().json

projectName = _('backend info').first().json["project name"]

# === Function to recursively add files ===
def add_files(zipf, obj, base=""):
    for name, val in obj.items():
        path = f"{base}/{name}" if base else name
        if isinstance(val, str):
            zipf.writestr(path, val)
        elif isinstance(val, dict):
            add_files(zipf, val, path)

# === Create zip in memory ===
zip_buffer = io.BytesIO()
with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zipf:
    add_files(zipf, project)

zip_buffer.seek(0)

# === Convert zip to Base64 ===
zip_base64 = base64.b64encode(zip_buffer.read()).decode("utf-8")

# === Return output in n8n format ===
return [
    {
        "json": {
            "fileName": f"{projectName}(BE).zip"
        },
        "binary": {
            "data": {
                "data": zip_base64,
                "mimeType": "application/zip",
                "fileName": f"{projectName}(BE).zip"
            }
        }
    }
]

import json
import zipfile
import io
import base64

# === INPUT ===
project = _input.item["json"]  # the entire folder structure JSON
project_name = _('frontend info').first().json["project name"]

# If root key is the project name (e.g. {"my-react-app": {...}}), unwrap it
if len(project.keys()) == 1 and isinstance(next(iter(project.values())), dict):
    project_root = next(iter(project.values()))
else:
    project_root = project

# === Function to recursively add files ===
def add_files(zipf, obj, base=""):
    for name, val in obj.items():
        path = f"{base}/{name}" if base else name

        if isinstance(val, str):
            # normal text file
            zipf.writestr(path, val)

        elif isinstance(val, dict):
            # case 1: dictionary that looks like a file (e.g., package.json)
            if any(isinstance(v, (str, int, float, bool, list, dict)) for v in val.values()):
                try:
                    content = json.dumps(val, indent=2)
                    zipf.writestr(path, content)
                except Exception:
                    add_files(zipf, val, path)
            else:
                # folder
                add_files(zipf, val, path)

        else:
            # fallback — convert other data types to string
            zipf.writestr(path, str(val))

# === Create zip in memory ===
zip_buffer = io.BytesIO()
with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zipf:
    add_files(zipf, project_root)

zip_buffer.seek(0)

# === Convert zip to Base64 ===
zip_base64 = base64.b64encode(zip_buffer.read()).decode("utf-8")

# === Return output for n8n ===
return [
    {
        "json": {
            "fileName": f"{project_name}.zip"
        },
        "binary": {
            "data": {
                "data": zip_base64,
                "mimeType": "application/zip",
                "fileName": f"{project_name}.zip"
            }
        }
    }
]

