// === INPUT ===
const input = $json;

// === Recursive flatten function (skips inside package.json) ===
function flattenJSON(obj, basePath = "") {
  let result = {};
  for (const key in obj) {
    const value = obj[key];
    const newPath = basePath ? `${basePath}/${key}` : key;

    if (key === "package.json") {
      // ✅ Keep package.json as a single file, not flattened
      if (typeof value === "object") {
        result[newPath] = JSON.stringify(value, null, 2);
      } else {
        result[newPath] = value;
      }
      continue; // skip recursion into it
    }

    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      Object.assign(result, flattenJSON(value, newPath));
    } else {
      result[newPath] = value;
    }
  }
  return result;
}

// === Detect the top-level project folder (e.g., JalJira) ===
const projectFolder = Object.keys(input)[0];
const projectData = input[projectFolder];

// === Flatten everything under that folder ===
const flattened = flattenJSON(projectData, projectFolder);

// === OUTPUT ===
return [
  {
    json: flattened
  }
];
